begin;

on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,difficulty=excluded.difficulty,estimated_minutes=excluded.estimated_minutes,status=excluded.status;

on conflict(id) do update set title=excluded.title,description=excluded.description,learning_objective=excluded.learning_objective;

on conflict(id) do update set title=excluded.title,instruction=excluded.instruction,audio_text=excluded.audio_text,safety_note=excluded.safety_note,expected_action=excluded.expected_action,options=excluded.options,hints=excluded.hints;

select class.id,version.id,administrator.user_id,'admin','active',true
from public.classes class cross join public.mission_versions version
cross join lateral(select a.user_id from public.administrators a where a.status='active' order by a.granted_at limit 1) administrator
where class.status='active' and version.id in ('20000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000008','20000000-0000-4000-8000-000000000009')
on conflict(class_id,mission_version_id) do nothing;

commit;
