insert into public.missions(id,slug,title,summary,category,difficulty,estimated_minutes,status) values
('10000000-0000-4000-8000-000000000007','identificar-mensagem-golpe','Identificar mensagem de golpe','Aprenda a reconhecer urgência, links suspeitos e pedidos de códigos.','Segurança digital','easy',6,'active'),
('10000000-0000-4000-8000-000000000008','falso-familiar-whatsapp','Golpe do falso familiar','Treine como confirmar a identidade de alguém antes de enviar dinheiro.','Segurança digital','medium',7,'active'),
('10000000-0000-4000-8000-000000000009','falsa-central-bancaria','Falsa central bancária','Reconheça ligações que pedem senha, código ou instalação de aplicativo.','Segurança digital','medium',7,'active')
insert into public.mission_versions(id,mission_id,version,status,title,description,learning_objective,content_language,changelog,published_at) values
('20000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000007',1,'published','Identificar mensagem de golpe','Simulação de mensagem suspeita sem abrir links reais.','Identificar sinais de golpe e escolher uma resposta segura.','pt-BR','Versão inicial',now()),
('20000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000008',1,'published','Golpe do falso familiar','Conversa fictícia com pedido urgente de dinheiro.','Confirmar a identidade por outro canal antes de agir.','pt-BR','Versão inicial',now()),
('20000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000009',1,'published','Falsa central bancária','Ligação bancária fictícia para reconhecer pedidos perigosos.','Interromper a chamada e procurar o canal oficial do banco.','pt-BR','Versão inicial',now())
insert into public.mission_steps(id,mission_version_id,position,step_type,title,instruction,audio_text,safety_note,expected_action,options,hints) values
('30000000-0000-4000-8000-000000000020','20000000-0000-4000-8000-000000000007',1,'multiple_choice','Observe a mensagem','Você ganhou um prêmio e precisa abrir um link agora. Qual é o principal sinal de perigo?','Uma mensagem promete prêmio e exige abrir um link agora. Qual é o sinal de perigo?','Nenhum link real será aberto.','{"action":"choose","option_id":"urgency-link"}','[{"id":"urgency-link","label":"Urgência e link desconhecido"},{"id":"logo","label":"A mensagem tem uma imagem"}]','["Golpistas tentam impedir que você tenha tempo para pensar."]'),
('30000000-0000-4000-8000-000000000021','20000000-0000-4000-8000-000000000007',2,'multiple_choice','Escolha a ação segura','O que você deve fazer com essa mensagem?','Escolha a ação mais segura.','Nada será apagado ou denunciado de verdade.','{"action":"choose","option_id":"ignore-check"}','[{"id":"open","label":"Abrir o link para conferir"},{"id":"ignore-check","label":"Não abrir e conferir no canal oficial"}]','["Entre no aplicativo oficial sem usar o link recebido."]'),
('30000000-0000-4000-8000-000000000022','20000000-0000-4000-8000-000000000007',3,'confirmation','Proteja seus códigos','Alguém pediu o código recebido por SMS. Escolha a resposta segura.','Códigos de confirmação são secretos.','Nenhum código existe nesta simulação.','{"action":"choose","option_id":"never-share"}','[{"id":"share","label":"Enviar o código"},{"id":"never-share","label":"Nunca compartilhar o código"}]','["Empresas sérias não pedem seu código de confirmação."]'),
('30000000-0000-4000-8000-000000000023','20000000-0000-4000-8000-000000000008',1,'multiple_choice','Receba o pedido urgente','Um novo número diz ser seu familiar e pede um Pix. O que fazer primeiro?','Um suposto familiar pede dinheiro por um número novo.','Nenhuma mensagem ou transferência será feita.','{"action":"choose","option_id":"call-known"}','[{"id":"pix","label":"Enviar para ajudar rápido"},{"id":"call-known","label":"Ligar para o número antigo e confirmar"}]','["Confirme por uma forma de contato que você já conhecia."]'),
('30000000-0000-4000-8000-000000000024','20000000-0000-4000-8000-000000000008',2,'multiple_choice','Faça uma pergunta','Qual pergunta ajuda a verificar a identidade?','Escolha algo que somente a pessoa verdadeira saberia.','A conversa é totalmente fictícia.','{"action":"choose","option_id":"private-question"}','[{"id":"name","label":"Qual é o seu nome?"},{"id":"private-question","label":"Perguntar algo conhecido apenas pela família"}]','["Nome e foto podem ser copiados por golpistas."]'),
('30000000-0000-4000-8000-000000000025','20000000-0000-4000-8000-000000000008',3,'confirmation','Decida com calma','Não conseguiu confirmar a identidade. O que fazer?','Sem confirmação, não envie dinheiro.','Nenhum contato real será bloqueado.','{"action":"choose","option_id":"do-not-pay"}','[{"id":"pay","label":"Enviar um valor menor"},{"id":"do-not-pay","label":"Não pagar e avisar a família"}]','["Urgência não substitui a confirmação."]'),
('30000000-0000-4000-8000-000000000026','20000000-0000-4000-8000-000000000009',1,'multiple_choice','Analise a ligação','A pessoa diz ser do banco e pede sua senha. Isso é seguro?','O banco ligou e pediu sua senha.','Nenhuma ligação real está acontecendo.','{"action":"choose","option_id":"unsafe"}','[{"id":"safe","label":"Sim, se souber meu nome"},{"id":"unsafe","label":"Não, senha nunca deve ser informada"}]','["Nome e outros dados podem ter vazado; isso não prova identidade."]'),
('30000000-0000-4000-8000-000000000027','20000000-0000-4000-8000-000000000009',2,'multiple_choice','Recuse o aplicativo','A pessoa pede para instalar um aplicativo de segurança. O que fazer?','Nunca instale aplicativos pedidos por uma ligação inesperada.','Nenhum download será iniciado.','{"action":"choose","option_id":"refuse"}','[{"id":"install","label":"Instalar enquanto ela orienta"},{"id":"refuse","label":"Recusar e encerrar a ligação"}]','["Aplicativos de acesso remoto permitem controlar seu celular."]'),
('30000000-0000-4000-8000-000000000028','20000000-0000-4000-8000-000000000009',3,'confirmation','Procure o canal oficial','Como falar com o banco depois de desligar?','Use o telefone do verso do cartão ou o aplicativo oficial.','Nenhum banco será contatado.','{"action":"choose","option_id":"official"}','[{"id":"callback","label":"Ligar para o número que apareceu na chamada"},{"id":"official","label":"Usar o aplicativo ou número oficial"}]','["Digite você mesmo o número oficial."]')
